static void Check(bool value,string name) { if (!value) throw new Exception(name); Console.WriteLine("PASS " + name); }
static async Task<string> Header(Stream s) { var b = new byte[1]; var text = new StringBuilder(); while (!text.ToString().EndsWith("\r\n\r\n")) { if (await s.ReadAsync(b) == 0) break; text.Append((char)b[0]); } return text.ToString(); }
static Task Send(Stream s,string text) => s.WriteAsync(Encoding.ASCII.GetBytes(text)).AsTask();
static async Task<string> Request(int port,string text) { using var c = new TcpClient(); await c.ConnectAsync(IPAddress.Loopback,port); await Send(c.GetStream(),text); var response = ""; string part; do { part=await Header(c.GetStream()).WaitAsync(TimeSpan.FromSeconds(15)); response+=part; } while (part.StartsWith("HTTP/1.1 1")); return response; }
static async Task<TcpClient> Tunnel(int port,int target) { var c = new TcpClient(); await c.ConnectAsync(IPAddress.Loopback,port); await Send(c.GetStream(),$"CONNECT localhost:{target} HTTP/1.1\r\nHost: localhost:{target}\r\nProxy-Authorization: secret\r\n\r\n"); var h = await Header(c.GetStream()); Check(h.Contains("200"),"CONNECT established"); return c; }
static async Task Echo(TcpClient c,string payload,string expected) { await Send(c.GetStream(),payload); var bytes = new byte[Encoding.ASCII.GetByteCount(expected)]; await c.GetStream().ReadExactlyAsync(bytes).AsTask().WaitAsync(TimeSpan.FromSeconds(5)); Check(Encoding.ASCII.GetString(bytes)==expected,"echo " + expected); }
