sealed class Fake : IAsyncDisposable
{
    readonly TcpListener listener = new(IPAddress.Loopback,0); readonly CancellationTokenSource cancel = new(); readonly List<TcpClient> clients = new(); readonly Task loop; readonly string marker; bool disposed;
    public int AcceptedCount; public int Port { get; } public string LastHeader=""; public string LastBody="";
    public Fake(string marker) { this.marker=marker; listener.Start(); Port=((IPEndPoint)listener.LocalEndpoint).Port; loop=Loop(); }
    async Task Loop() { try { while (!cancel.IsCancellationRequested) { var c=await listener.AcceptTcpClientAsync(cancel.Token); Interlocked.Increment(ref AcceptedCount); lock(clients) clients.Add(c); _=Serve(c); } } catch(OperationCanceledException) {} }
    async Task Serve(TcpClient c) { try { using(c) { var s=c.GetStream(); if(marker == "") { var eb=new byte[32768]; int en; while((en=await s.ReadAsync(eb,cancel.Token))>0) await s.WriteAsync(eb.AsMemory(0,en),cancel.Token); return; } var bytes=new List<byte>(); var one=new byte[1]; while (bytes.Count<20000) { if(await s.ReadAsync(one,cancel.Token)==0)return; bytes.Add(one[0]); if(bytes.Count>=4 && Encoding.ASCII.GetString(bytes.TakeLast(4).ToArray())=="\r\n\r\n")break; } LastHeader=Encoding.ASCII.GetString(bytes.ToArray());
        if(LastHeader.StartsWith("CONNECT")) { if(marker=="stall") { await Task.Delay(Timeout.Infinite,cancel.Token); return; } await s.WriteAsync(Encoding.ASCII.GetBytes(marker=="reject"?"HTTP/1.1 403 Forbidden\r\nContent-Length: 0\r\n\r\n":"HTTP/1.1 200 OK\r\n\r\n")); if(marker=="reject")return; var buffer=new byte[32768]; int n; while((n=await s.ReadAsync(buffer,cancel.Token))>0) { await s.WriteAsync(Encoding.ASCII.GetBytes(marker),cancel.Token); await s.WriteAsync(buffer.AsMemory(0,n),cancel.Token); } }
        else { var lengthLine=LastHeader.Split("\r\n").FirstOrDefault(x=>x.StartsWith("Content-Length:",StringComparison.OrdinalIgnoreCase)); if(lengthLine!=null) { var body=new byte[int.Parse(lengthLine.Split(':')[1])]; await s.ReadExactlyAsync(body,cancel.Token); LastBody=Encoding.ASCII.GetString(body); } if(LastHeader.Contains("Transfer-Encoding: chunked")) { var body=new StringBuilder(); while(!body.ToString().EndsWith("0\r\n\r\n")) { await s.ReadExactlyAsync(one,cancel.Token); body.Append((char)one[0]); } LastBody=body.ToString(); } if(marker=="hints") await s.WriteAsync(Encoding.ASCII.GetBytes("HTTP/1.1 103 Early Hints\r\nLink: </asset>; rel=preload\r\n\r\n")); await s.WriteAsync(Encoding.ASCII.GetBytes("HTTP/1.1 200 OK\r\nContent-Length: 2\r\nConnection: close\r\n\r\nOK")); }
    } } catch(Exception ex) when(ex is IOException or SocketException or OperationCanceledException or ObjectDisposedException) {} }
    public async ValueTask DisposeAsync() { if(disposed)return; disposed=true; cancel.Cancel(); listener.Stop(); lock(clients)foreach(var c in clients)c.Dispose(); await loop; cancel.Dispose(); }
}
